const body = $json.body || {};
const headers = $json.headers || {};
const expectedSecret = String($env.WHATSAPP_N8N_FORWARD_SECRET || '').trim();
const receivedSecret = String(headers['x-lms-whatsapp-secret'] || headers['X-Lms-Whatsapp-Secret'] || '').trim();

if (expectedSecret && receivedSecret !== expectedSecret) {
  throw new Error('Invalid LMS WhatsApp forwarding secret');
}

const normalizeWhatsAppNumber = (value) => {
  const digits = String(value || '').replace(/\D/g, '');
  return digits.length === 10 ? `91${digits}` : digits;
};

const rawRecipients = Array.isArray(body.recipients) && body.recipients.length
  ? body.recipients
  : body.to
    ? [body.to]
    : [];

const recipients = [...new Set(rawRecipients.map(normalizeWhatsAppNumber).filter(Boolean))];
if (!recipients.length) throw new Error('No WhatsApp recipients provided');

const bodyComponent = Array.isArray(body.components)
  ? body.components.find((component) => String(component?.type || '').toLowerCase() === 'body')
  : null;

const componentParameters = Array.isArray(bodyComponent?.parameters)
  ? bodyComponent.parameters
      .map((parameter) => String(parameter?.text ?? parameter?.value ?? '').slice(0, 1024))
      .filter(Boolean)
  : [];

const rawBodyParameters = Array.isArray(body.bodyParameters)
  ? body.bodyParameters
  : Array.isArray(body.templateVariables)
    ? body.templateVariables
    : componentParameters;

const bodyParameters = rawBodyParameters
  .map((value) => String(value || '').trim().slice(0, 1024))
  .filter(Boolean);

const templateName = String(body.templateName || body.template_name || '').trim();
if (!templateName) throw new Error('No WhatsApp template name provided');

const language = String(body.language || body.language_code || 'en_US').trim();
const phoneNumberId = String($env.WHATSAPP_PHONE_NUMBER_ID || '').trim();
const accessTokenPresent = Boolean(String($env.WHATSAPP_ACCESS_TOKEN || '').trim());
if (!phoneNumberId) throw new Error('WHATSAPP_PHONE_NUMBER_ID is not configured in n8n');
if (!accessTokenPresent) throw new Error('WHATSAPP_ACCESS_TOKEN is not configured in n8n');

const graphVersionRaw = String($env.WHATSAPP_GRAPH_VERSION || 'v25.0').trim();
const graphVersion = graphVersionRaw.startsWith('v') ? graphVersionRaw : `v${graphVersionRaw}`;
const endpoint = `https://graph.facebook.com/${graphVersion}/${phoneNumberId}/messages`;

return recipients.map((to) => {
  const components = bodyParameters.length
    ? [{ type: 'body', parameters: bodyParameters.map((text) => ({ type: 'text', text })) }]
    : undefined;

  return {
    json: {
      to,
      templateName,
      language,
      bodyParameters,
      endpoint,
      metaBody: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to,
        type: 'template',
        template: {
          name: templateName,
          language: { code: language },
          ...(components ? { components } : {}),
        },
      },
      metadata: body.metadata || {},
      debug: {
        sender: 'n8n_graph_api_http_request',
        endpoint,
        graphVersion,
        phoneNumberId,
        to,
        templateName,
        templateLanguage: language,
        bodyParameterCount: bodyParameters.length,
        accessTokenPresent,
      },
    },
  };
});

const sentItems = $input.all();
const requestItems = $items('Prepare Meta Template Requests');

const errorText = (value) => {
  if (!value) return '';
  if (typeof value === 'string') return value;
  return String(value.message || value.error_user_msg || value.error || JSON.stringify(value));
};

const results = sentItems.map((item, index) => {
  const response = item.json || {};
  const request = requestItems[index]?.json || {};
  const message = Array.isArray(response.messages) ? response.messages[0] : null;
  const metaError = response.error || null;
  const error = errorText(metaError || response.message || response.errorDescription);
  const ok = Boolean(message?.id) && !error;

  return {
    phoneNumber: request.to || response.to || '',
    to: request.to || response.to || '',
    ok,
    status: ok ? (message?.message_status || 'accepted') : 'failed',
    metaMessageId: message?.id || '',
    templateName: request.templateName || '',
    messageType: 'template',
    error: ok ? '' : error || 'WhatsApp send failed in n8n',
    metaError,
    debug: {
      ...(request.debug || {}),
      rawResponse: response,
    },
  };
});

return [{ json: { ok: results.every((result) => result.ok), results } }];
